"""Money conversion helpers.

Amounts are represented as integer minor units (e.g. cents).  Conversion from
human-readable amounts must never route through binary floating point.
"""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

_CENT = Decimal("0.01")


def _to_decimal(amount):
    """Convert a supported amount to an exact Decimal, or raise ValueError."""
    if isinstance(amount, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(amount, Decimal):
        value = amount
    elif isinstance(amount, int):
        value = Decimal(amount)
    elif isinstance(amount, str):
        text = amount.strip()
        if not text:
            raise ValueError("empty amount string")
        try:
            value = Decimal(text)
        except (InvalidOperation, ValueError):
            raise ValueError("invalid amount string: %r" % (amount,))
    else:
        raise ValueError("unsupported amount type: %s" % type(amount).__name__)

    if not value.is_finite():
        raise ValueError("amount must be finite")
    return value


def money_minor(amount):
    """Convert an amount to integer minor units (cents).

    Accepts a decimal string, an ``int``, or a ``Decimal``.  Values are rounded
    to the nearest cent using half-up rounding (the project convention for
    monetary amounts).  Negative amounts are supported.  ``bool``, NaN,
    Infinity, and any other type raise ``ValueError``.
    """
    value = _to_decimal(amount)
    try:
        rounded = value.quantize(_CENT, rounding=ROUND_HALF_UP)
    except InvalidOperation:
        raise ValueError("amount out of range: %r" % (amount,))
    return int(rounded.scaleb(2))

