"""UTC timestamp normalization helpers."""

from datetime import datetime, timezone


def utc_stamp(value):
    """Return an ISO-8601 UTC timestamp with second precision and a trailing ``Z``.

    ``value`` must be a string containing a ``T``-separated date and time.
    Explicit UTC offsets are converted to UTC. Naive datetimes are interpreted
    as UTC (the project convention) rather than in the host local timezone.
    Date-only strings, non-strings, and malformed values raise ``ValueError``.
    """
    if not isinstance(value, str):
        raise ValueError("timestamp must be a string")

    text = value.strip()
    if "T" not in text and "t" not in text:
        raise ValueError("timestamp must include a time component")

    try:
        parsed = datetime.fromisoformat(text)
    except (TypeError, ValueError) as exc:
        raise ValueError("invalid ISO-8601 timestamp") from exc

    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    else:
        parsed = parsed.astimezone(timezone.utc)

    return parsed.replace(microsecond=0).strftime("%Y-%m-%dT%H:%M:%SZ")

